package dev.atoll.app.model

import dev.atoll.app.core.*
import kotlinx.serialization.json.*
import org.junit.Assert.assertEquals
import org.junit.Test

/** Golden folds captured directly from the web authority with a fixed random seed.
 * Includes arbitrary graphs, partial links, flat ingress, shuffled arrivals, trim,
 * and request replay. Expected data is independent of the Kotlin implementation.
 */
class WebGoldenTest {
    @Test fun matchesWebAuthorityIncludingTrimAndReplay() {
        val cases = GOLDENS.map(Json::parseToJsonElement)
        for ((index, value) in cases.withIndex()) {
            val case = value.jsonObject
            val replica = ChannelReplica(CHANNEL)
            fun admit(key: String) {
                val rows = case.getValue(key).jsonArray.map { item ->
                    val row = item.jsonObject
                    Row(CHANNEL, row.getValue("seq").jsonPrimitive.long, Envelope(row.getValue("envelope").jsonObject))
                }
                replica.add(*rows.toTypedArray())
            }
            admit("rows")
            val trim = case.getValue("trim").jsonPrimitive.int
            if (trim > 0) replica.trim(trim, false)
            admit("replay")
            assertEquals("web golden $index", case.getValue("expected"), signature(replica.snapshot()))
        }
    }
    private fun signature(state: ReplicaSnapshot): JsonObject = buildJsonObject {
        put("timeline", JsonArray(state.timeline.map(::entrySignature)))
        put("narration", JsonArray(state.narration.map { JsonPrimitive("${it.seq}:${it.envelope.id}") }))
        put("envelopes", JsonArray(state.envelopesById.keys.sorted().map(::JsonPrimitive)))
        put("lastSeq", state.lastSeq)
    }
    private fun entrySignature(entry: TimelineEntry): JsonObject = buildJsonObject {
        put("kind", entry.kind); put("seq", entry.seq)
        val turn = entry.turn
        if (turn == null) put("envelope", entry.envelope?.id.orEmpty()) else {
            put("turn", buildJsonObject {
                put("requestId", turn.requestId); put("request", turn.request.id)
                put("requestSeq", turn.requestSeq); put("lastSeq", turn.lastSeq)
                put("status", turn.status); put("terminal", turn.terminal?.id.orEmpty())
                put("terminalSeq", turn.terminalSeq); put("terminalClosureOnly", turn.terminalClosureOnly)
                put("provisional", JsonArray(turn.provisional.map { JsonPrimitive("${it.seq}:${it.envelope.id}") }))
            })
            put("thread", JsonArray(entry.thread.map(::entrySignature)))
        }
    }
